// Nonghyup Bank Deposit Notification Email Parser
const item = $input.first().json;
const content = (item.text || '') + '\n' + (item.html || '') + '\n' + (item.subject || '');

// 1. Account Number matching
const accountMatch = content.match(/130027-?52-?081538/);
const account = accountMatch ? '130027-52-081538' : '130027-52-081538';

// 2. Date & Time matching (언제)
// Matches standard formats like 2026-08-12 10:15:30, 2026.08.12 10:15, 08/12 10:15 etc.
let dateMatch = content.match(/(\d{4}[-.\/]\d{2}[-.\/]\d{2}\s+\d{2}:\d{2}(?::\d{2})?)/);
if (!dateMatch) {
  dateMatch = content.match(/(거래일시|일시)[:\s]*([\d-.\/:\s]+)/);
}
const depositDate = dateMatch ? (dateMatch[1] || dateMatch[2]).trim() : new Date().toLocaleString('ko-KR');

// 3. Depositor / Sender matching (누가)
// Matches '보내신분:', '입금자:', '적요:', '보낸이:', or bracket pattern '[NH농협] 홍길동'
let depositorMatch = content.match(/(?:보내신분|입금자|보낸이|적요)[:\s]*([^\r\n<,]+)/);
if (!depositorMatch) {
  depositorMatch = content.match(/(?:입금|통지)[:\s]*([^\r\n<,]+님|[^\r\n<,]+)/);
}
let depositor = depositorMatch ? depositorMatch[1].trim() : '미확인 (알 수 없음)';
// Clean up common prefix labels, suffix, or HTML tags
depositor = depositor.replace(/<[^>]*>/g, '').replace(/^(?:\(적요\)|보내신분|입금자|보낸이)[:\s]*/, '').replace(/님$/, '').trim();

// 4. Deposit Amount (얼마)
let amountMatch = content.match(/(?:입금금액|입금액|금액)[:\s]*([\d,]+)(?:\s*원)?/);
let amountStr = amountMatch ? amountMatch[1].replace(/,/g, '') : '0';
const amount = parseInt(amountStr, 10) || 0;

// 5. Balance (잔액)
let balanceMatch = content.match(/(?:거래후잔액|잔액)[:\s]*([\d,]+)(?:\s*원)?/);
let balanceStr = balanceMatch ? balanceMatch[1].replace(/,/g, '') : '0';
const balance = parseInt(balanceStr, 10) || 0;

return {
  json: {
    account: account,
    recipientEmail: 'himin50@gmail.com',
    depositDate: depositDate,
    depositor: depositor,
    amount: amount,
    balance: balance,
    subject: item.subject || '농협 입출금 알림',
    timestamp: new Date().toISOString()
  }
};
